<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_permission('MOVIMIENTO_CANCELAR');$in=json_input();$id=(int)($in['movimiento_id']??0);$reason=trim((string)($in['motivo']??''));if($id<=0||strlen($reason)<5)json_response(['ok'=>false,'error'=>'Indica el movimiento y un motivo de cancelación'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$st=$db->prepare("SELECT * FROM presupuesto_movimiento WHERE movimiento_id=? LIMIT 1");$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();$st->close();if(!$row){$db->close();json_response(['ok'=>false,'error'=>'Movimiento no encontrado'],404);}if($row['estatus']==='CANCELADO'){$db->close();json_response(['ok'=>false,'error'=>'El movimiento ya está cancelado'],409);}if(!movement_is_visible($db,$user,$row)&&!user_is_global($user)){$db->close();json_response(['ok'=>false,'error'=>'Sin acceso al movimiento'],403);}$uid=(int)$user['user_id'];$st=$db->prepare("UPDATE presupuesto_movimiento SET estatus='CANCELADO',cancelado_por_usuario_id=?,cancelado_at=NOW(),motivo_cancelacion=? WHERE movimiento_id=?");$st->bind_param('isi',$uid,$reason,$id);$st->execute();$st->close();audit_log($db,$uid,'MOVIMIENTO_CANCELAR','MOVIMIENTO',$id,$reason,$row,['estatus'=>'CANCELADO','motivo'=>$reason]);$db->close();json_response(['ok'=>true]);
